def generate(seed):
    r = random.Random(seed)
    for _ in range(600):
        G = r.choice((7, 7, 8, 8, 9, 9, 10, 10))
        n = G - r.choice((2, 3, 4, 5, 6, 6))
        if n < 2:
            continue
        lo = r.choice((2, 2, 3, 3, 4))
        gaps = [r.choice((lo, lo, lo + 1)) for _ in range(G)]
        if len(set(gaps)) < 2:
            continue
        hits = [1] * (G + 1)
        base = sum(gaps) + G + 1
        L = 4 * ((base + 3) // 4) + 4 * r.choice((0, 0, 1))
        left = L - base
        if L > 48 or L < 28 or left > 2 * (G + 1):
            continue
        for _ in range(left):
            for _t in range(40):
                i = r.randrange(G + 1)
                if hits[i] < 3:
                    hits[i] += 1
                    break
        if sum(hits) + sum(gaps) != L:
            continue
        K = "".join("x" * hits[i] + "." * gaps[i] for i in range(G)) + "x" * hits[G]
        wide = max(gaps)
        bad = {G, G + 1, sum(hits), wide, L // 4,
               gaps.count(wide), gaps.count(lo), hits.count(3)}
        if n in bad:
            continue
        return K + "/" + str(n)
    return "x..x...xx..x..xx..x..x..x...x..x...x/5"

