def sp(row, ch):
 out, i, L = [], 0, len(row)
 while i < L:
  if row[i] == ch:
   j = i
   while j < L and row[j] == ch:
    j += 1
   out.append((i, j))
   i = j
  else:
   i += 1
 return out

def build(K, gp, fills, r):
 """snare row: the n exact fills, a few planted near-misses, nothing else."""
 L = len(K)
 row = ["."] * L
 used = set()

 def put(a, b):
  for i in range(a, b):
   row[i] = "x"
  used.update(range(a, b))

 def free(a, b):                 # placeable without merging into a neighbouring run
  return 0 <= a and b <= L and all(i not in used for i in range(a - 1, b + 1))

 for g in fills:
  put(*g)
 ws = sorted({b - a for a, b in gp})
 for _ in range(r.choice((1, 1, 1, 2))):       # a run as long as a hole, in the wrong place
  cand = [(p, p + l) for l in ws for p in range(L - l + 1)
          if (p, p + l) not in gp and free(p, p + l) and any(K[i] == "x" for i in range(p, p + l))]
  if cand:
   put(*r.choice(cand))
 rest = [g for g in gp if g not in fills]
 r.shuffle(rest)
 need = ["spill", "sl", "sr"]
 r.shuffle(need)
 modes = need
 for g, m in zip(rest, modes):                 # every other hole stays silent
  a, b = g
  w = b - a
  if m == "spill":
   if r.random() < 0.5 and free(a - 1, b):
    put(a - 1, b)
    continue
   if free(a, b + 1):
    put(a, b + 1)
    continue
   if free(a - 1, b):
    put(a - 1, b)
    continue
   m = r.choice(("sl", "sr"))
  if m == "sl" and w > 1 and free(a, b - 1):
   put(a, a + r.randint(1, w - 1))
  elif m == "sr" and w > 1 and free(a + 1, b):
   put(b - r.randint(1, w - 1), b)
  elif m == "si" and w > 2 and free(a + 1, b - 1):
   l = r.randint(1, w - 2)
   o = r.randint(1, w - 1 - l)
   put(a + o, a + o + l)
 S = "".join(row)
 return S if [g for g in sp(S, "x") if g in fills] == sorted(fills) else None

def ok(K, S, gp, n, lvl):
 L = len(K)
 gs = set(gp)
 gl = {b - a for a, b in gp}
 rs = sp(S, "x")
 fit = [g for g in rs if g in gs]
 if len(fit) != n:
  return 0
 inside = [g for g in rs if g not in gs and any(a <= g[0] and g[1] <= b for a, b in gp)]
 over = [g for g in rs if any(g[0] <= a and b <= g[1] for a, b in gp) and g not in gs]
 away = [g for g in rs if g not in gs and (g[1] - g[0]) in gl and
         not any(a <= g[0] and g[1] <= b for a, b in gp)]
 if not (inside and over and away):
  return 0
 if not lvl and max(b - a for a, b in fit) < max(gl):
  return 0
 hit = lambda a, b: any(S[i] == "x" for i in range(a, b))
 riv = [len(rs), S.count("x"), len(inside), len(over), len(away), len(inside) + n,
        sum(1 for a, b in gp if hit(a, b)), sum(1 for a, b in gp if not hit(a, b)),
        sum(1 for g in rs if g[0] in {a for a, b in gp}),
        sum(1 for g in rs if g[1] in {b for a, b in gp}),
        sum(1 for i in range(L) if S[i] == K[i] == "x"),
        sum(1 for g in rs if any(K[i] == "x" for i in range(*g))),
        sum(1 for g in rs if (g[1] - g[0]) in gl),
        len({g[1] - g[0] for g in rs}), max(g[1] - g[0] for g in rs),
        sum(1 for i in range(0, L, 4) if hit(i, min(i + 4, L))),
        sum(1 for a, b in gp if sum(1 for i in range(a, b) if S[i] == "x") == 1)]
 return all(v != n for v in riv[:6 if lvl else len(riv)])

def rend(K, S, r):
 nm = r.choice(NM)
 w = max(len(x) for x in nm)
 out = []
 st = r.random()
 lab = st > 0.12
 if st < 0.8:
  if r.random() < 0.35:
   out.append(" " * (w + 1) * lab + "|" + "|".join("1234" for _ in range(len(K) // 4)) + "|")
  for a, row in zip(nm, (K, S)):
   out.append(a.rjust(w) * lab + " " * lab + "|" +
              "|".join(row[i:i + 4] for i in range(0, len(K), 4)) + "|")
 else:
  for a, row in zip(nm, (K, S)):
   out.append((a.rjust(w) + " " + row) if lab else row)
 return "\n".join(out)

def solve(clue):
 K, ns = clue.split("/")
 n = int(ns)
 r = random.Random(clue)
 gp = sp(K, ".")
 wide = [i for i in range(len(gp)) if gp[i][1] - gp[i][0] == max(b - a for a, b in gp)]
 for t in range(1600):
  idx = list(range(len(gp)))
  r.shuffle(idx)
  if r.random() < 0.9:
   w = r.choice(wide)
   idx.remove(w)
   idx.insert(r.randrange(n), w)
  S = build(K, gp, sorted(gp[i] for i in idx[:n]), r)
  if S is not None and ok(K, S, gp, n, t // 1400):
   return rend(K, S, r)
 S = ["."] * len(K)
 for a, b in r.sample(gp, min(n, len(gp))):
  S[a:b] = "x" * (b - a)
 return rend(K, "".join(S), r)

